# Calculate N for f(x, y) = x + y
L = 100
N = 0
for x in range(L):
    for y in range(L):
        # f(x, y) = x + y
        if (x + y) % 2 != 0:
            N += 1
print(f"N for f(x, y) = x + y is: {N}")

